func inRanges(r rune, ranges [][2]rune) bool {
	lo, hi := 0, len(ranges)
	for lo < hi {
		mid := (lo + hi) / 2
		if r < ranges[mid][0] {
			hi = mid
		} else if r > ranges[mid][1] {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}
